/* ============================================
   CommerceForge Dev Docs — Stylesheet
   Dark-mode-first | #0d1117 canvas | Cyan accents
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2333;
  --bg-card: rgba(22, 27, 34, 0.8);
  --bg-card-hover: rgba(30, 38, 50, 0.9);
  --border: rgba(56, 68, 89, 0.5);
  --border-hover: rgba(70, 130, 180, 0.6);
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00d4aa;
  --accent-bright: #00f0c0;
  --accent-dim: rgba(0, 212, 170, 0.15);
  --accent-blue: #475f91;
  --accent-blue-bright: #5876b3;
  --code-bg: #0d1117;
  --sidebar-width: 260px;
  --sidebar-collapsed: 0px;
  --nav-height: 60px;
  --max-width: 1200px;
  --radius: 8px;
  --radius-lg: 12px;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --font-body: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-bright); }

h1, h2, h3, h4, h5, h6 { line-height: 1.25; font-weight: 600; color: var(--text-primary); }
h1 { font-size: clamp(2rem, 5vw, 3rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2rem); margin-bottom: 0.75em; }
h3 { font-size: 1.25rem; margin-bottom: 0.5em; }

img { max-width: 100%; display: block; }

/* --- Top Navigation --- */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-height);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  height: 100%;
  gap: 2rem;
}

.nav-brand {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.nav-brand svg { flex-shrink: 0; }

.nav-links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
  flex: 1;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 0.25rem 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  border-bottom-color: var(--accent);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.nav-search {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.4rem 0.75rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.nav-search:hover { border-color: var(--border-hover); }

.nav-search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.1rem 0.35rem;
  font-size: 0.7rem;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.btn-login {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 0.4rem 1rem;
  border-radius: var(--radius);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-login:hover { border-color: var(--accent); color: var(--accent); }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 0.25rem;
}

/* --- Layout Containers --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.page-content { padding: 3rem 0; }

/* --- Layout with Sidebar --- */
.layout-with-sidebar {
  display: flex;
  gap: 2rem;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  position: sticky;
  top: calc(var(--nav-height) + 2rem);
  max-height: calc(100vh - var(--nav-height) - 4rem);
  overflow-y: auto;
  transition: width var(--transition), opacity var(--transition), margin var(--transition);
}

.sidebar.collapsed {
  width: 0;
  opacity: 0;
  margin-right: -2rem;
  overflow: hidden;
  pointer-events: none;
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.35rem 0.7rem;
  color: var(--text-secondary);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all var(--transition);
  margin-bottom: 1rem;
  white-space: nowrap;
}

.sidebar-toggle:hover { border-color: var(--border-hover); color: var(--text-primary); }

.sidebar-nav { list-style: none; }

.sidebar-nav li { margin-bottom: 0.25rem; }

.sidebar-nav a {
  display: block;
  padding: 0.4rem 0.75rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  border-radius: var(--radius);
  border-left: 2px solid transparent;
  transition: all var(--transition);
}

.sidebar-nav a:hover {
  color: var(--text-primary);
  background: var(--accent-dim);
  border-left-color: var(--accent);
}

.sidebar-nav a.active {
  color: var(--accent);
  background: var(--accent-dim);
  border-left-color: var(--accent);
}

.sidebar-section-title {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  padding: 1rem 0.75rem 0.35rem;
  font-weight: 600;
}

.main-content { flex: 1; min-width: 0; }

/* --- Hero Sections --- */
.hero {
  padding: 4rem 0;
  border-bottom: 1px solid var(--border);
}

.hero-home {
  padding: 5rem 0 3rem;
  text-align: center;
  background: radial-gradient(ellipse at 50% 0%, rgba(0, 212, 170, 0.06) 0%, transparent 60%);
}

.hero h1 { margin-bottom: 1rem; }

.hero h1 .accent { color: var(--accent); }

.hero .subtitle {
  color: var(--text-secondary);
  font-size: 1.1rem;
  max-width: 680px;
  margin: 0 auto 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-primary);
}

.btn-primary:hover {
  background: var(--accent-bright);
  color: var(--bg-primary);
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0, 212, 170, 0.3);
}

.btn-secondary {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-primary);
}

.btn-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.btn-ghost {
  background: var(--accent-dim);
  color: var(--accent);
  padding: 0.5rem 1rem;
}

.btn-ghost:hover {
  background: rgba(0, 212, 170, 0.25);
}

/* --- Cards --- */
.card-grid {
  display: grid;
  gap: 1.5rem;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-2 { grid-template-columns: repeat(2, 1fr); }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  transition: all var(--transition);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.card:hover {
  border-color: var(--border-hover);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
}

.card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius);
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
  color: var(--accent);
}

.card h3 { margin-bottom: 0.5rem; }

.card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 1rem;
}

.card .card-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  color: var(--accent);
  font-weight: 600;
  font-size: 0.9rem;
  transition: gap var(--transition);
}

.card .card-cta:hover { gap: 0.6rem; }

/* Product cards specific */
.product-card {
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent), transparent);
  opacity: 0;
  transition: opacity var(--transition);
}

.product-card:hover::before { opacity: 1; }

/* --- CLI Setup Section --- */
.cli-section {
  padding: 4rem 0;
}

.cli-header {
  text-align: center;
  margin-bottom: 3rem;
}

.cli-header .subtitle {
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0.75rem auto 0;
  line-height: 1.7;
}

.cli-accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 0.75rem;
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active { border-color: var(--accent); }

.accordion-trigger {
  width: 100%;
  background: var(--bg-secondary);
  border: none;
  padding: 1.1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition);
}

.accordion-trigger:hover { background: var(--bg-tertiary); }

.accordion-trigger .chevron {
  transition: transform var(--transition);
  color: var(--text-muted);
}

.accordion-item.active .accordion-trigger .chevron {
  transform: rotate(180deg);
  color: var(--accent);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-body-inner {
  padding: 1.25rem 1.5rem;
}

.step-list {
  list-style: none;
  counter-reset: steps;
}

.step-list li {
  counter-increment: steps;
  padding: 0.6rem 0;
  padding-left: 2.2rem;
  position: relative;
  color: var(--text-secondary);
  font-size: 0.9rem;
  border-bottom: 1px solid rgba(56, 68, 89, 0.2);
}

.step-list li:last-child { border-bottom: none; }

.step-list li::before {
  content: counter(steps);
  position: absolute;
  left: 0;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* --- Tabs --- */
.tab-group { margin-top: 1rem; }

.tab-bar {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0;
}

.tab-btn {
  background: transparent;
  border: none;
  padding: 0.6rem 1.2rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-family: var(--font-mono);
  font-weight: 500;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}

.tab-btn:hover { color: var(--text-primary); }

.tab-btn.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.tab-panel {
  display: none;
  padding: 0.75rem 0;
}

.tab-panel.active { display: block; }

/* --- Code Blocks --- */
.code-block {
  background: var(--code-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  line-height: 1.7;
  color: var(--accent-bright);
  overflow-x: auto;
  position: relative;
}

.code-block .copy-btn {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.25rem 0.5rem;
  color: var(--text-muted);
  font-size: 0.7rem;
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--transition);
}

.code-block:hover .copy-btn { opacity: 1; }

.code-inline {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--bg-tertiary);
  padding: 0.15rem 0.4rem;
  border-radius: 4px;
  color: var(--accent);
}

/* --- Launch CTA --- */
.launch-section {
  padding: 4rem 0;
  border-top: 1px solid var(--border);
}

.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.launch-card h3 { margin-bottom: 0.5rem; }

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  flex: 1;
  margin-bottom: 1.25rem;
}

/* --- Community Section --- */
.community-section {
  padding: 4rem 0;
  border-top: 1px solid var(--border);
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  transition: all var(--transition);
  text-align: center;
}

.community-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
}

.community-card .community-icon {
  width: 36px;
  height: 36px;
  margin: 0 auto 0.75rem;
  color: var(--accent);
}

.community-card h4 {
  font-size: 0.9rem;
  margin-bottom: 0.25rem;
}

.community-card p {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* --- Section Titles --- */
.section-title {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  font-weight: 700;
  margin-bottom: 0.5rem;
}

/* --- Content Sections --- */
.content-section {
  padding: 3rem 0;
  border-top: 1px solid var(--border);
}

.content-section:first-of-type { border-top: none; }

.section-header {
  margin-bottom: 2rem;
}

.section-header p {
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.7;
}

/* --- Surface / Building Block Grid --- */
.surface-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.surface-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  transition: all var(--transition);
}

.surface-card:hover {
  border-color: var(--border-hover);
}

.surface-card h4 {
  font-size: 0.95rem;
  margin-bottom: 0.35rem;
}

.surface-card p {
  font-size: 0.8rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Best Practices --- */
.practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.practice-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem;
}

.practice-icon {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  margin-top: 2px;
}

.practice-item h4 { font-size: 0.9rem; margin-bottom: 0.15rem; }
.practice-item p { font-size: 0.8rem; color: var(--text-secondary); }

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: flex;
  justify-content: center;
  gap: 2rem;
  flex-wrap: wrap;
  padding: 2rem 0;
}

.protocol-actor {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem 2rem;
  text-align: center;
  min-width: 140px;
  transition: all var(--transition);
}

.protocol-actor:hover { border-color: var(--accent); }

.protocol-actor .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.75rem;
  color: var(--accent);
}

.protocol-actor h4 { margin-bottom: 0.25rem; }
.protocol-actor p { font-size: 0.8rem; color: var(--text-secondary); }

/* --- Status Badge --- */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  background: rgba(255, 166, 0, 0.12);
  color: #ffa600;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.65rem;
  border-radius: 20px;
}

.status-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ffa600;
}

/* --- Support Cards --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all var(--transition);
}

.support-card:hover { border-color: var(--border-hover); }

.support-card h4 { margin-bottom: 0.35rem; }
.support-card p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.5; }

/* --- Footer --- */
.site-footer {
  border-top: 1px solid var(--border);
  padding: 3rem 0 2rem;
  margin-top: 2rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.footer-col h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 0.35rem; }

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--accent); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 2rem auto 0;
  padding: 1.5rem 1.5rem 0;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .surface-grid { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search { display: none; }
  .mobile-menu-btn { display: flex; }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    padding: 1rem 1.5rem;
    gap: 0.75rem;
  }

  .card-grid-3,
  .card-grid-2,
  .launch-grid,
  .support-grid { grid-template-columns: 1fr; }

  .surface-grid,
  .practices-grid { grid-template-columns: 1fr; }

